      "name": "natCast_le_analyticOrderAt_iff_iteratedDeriv_eq_zero",
      "module_name": "Mathlib.Analysis.Analytic.Order",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {f : 𝕜 → E} {n : ℕ} {z₀ : 𝕜} [CharZero 𝕜] [CompleteSpace E],\n  AnalyticAt 𝕜 f z₀ → (↑n ≤ analyticOrderAt f z₀ ↔ ∀ i < n, iteratedDeriv i f z₀ = 0)"
    },
    {
      "name": "MvPolynomial.IsWeightedHomogeneous.pderiv",
      "module_name": "Mathlib.RingTheory.MvPolynomial.EulerIdentity",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_2} {M : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R}\n  [inst_1 : AddCancelCommMonoid M] {w : σ → M} {n n' : M} {i : σ},\n  MvPolynomial.IsWeightedHomogeneous w φ n →\n    n' + w i = n → MvPolynomial.IsWeightedHomogeneous w ((MvPolynomial.pderiv i) φ) n'"
    },
