    },
    {
      "name": "AddMonoidAlgebra.le_inf_support_list_prod",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} [inst : SemilatticeInf T] [inst_1 : OrderTop T] [inst_2 : Semiring R]\n  [inst_3 : AddMonoid A] [inst_4 : AddMonoid T] [AddLeftMono T] [AddRightMono T] {degt : A → T},\n  0 ≤ degt 0 →\n    (∀ (a b : A), degt a + degt b ≤ degt (a + b)) →\n      ∀ (l : List (AddMonoidAlgebra R A)), (List.map (fun f => f.support.inf degt) l).sum ≤ l.prod.support.inf degt"
    },
    {
      "name": "AddMonoidAlgebra.le_inf_support_pow",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} [inst : SemilatticeInf T] [inst_1 : OrderTop T] [inst_2 : Semiring R]\n  [inst_3 : AddMonoid A] [inst_4 : AddMonoid T] [AddLeftMono T] [AddRightMono T] {degt : A → T},\n  0 ≤ degt 0 →\n    (∀ (a b : A), degt a + degt b ≤ degt (a + b)) →\n      ∀ (n : ℕ) (f : AddMonoidAlgebra R A), n • f.support.inf degt ≤ (f ^ n).support.inf degt"
